# Secure File Deletion Script

This script provides multiple methods for securely deleting files from a hard drive. Note that this is a destructive operation - once files are deleted this way, they cannot be recovered.

## PowerShell Script (Windows)

```powershell
<#
.SYNOPSIS
    Securely deletes files from a hard drive
.DESCRIPTION
    This script provides multiple secure deletion methods including simple deletion,
    DoD 5220.22-M compliant wiping (3 passes), and Gutmann method (35 passes).
.NOTES
    Run this script as Administrator for best results
    THIS IS DESTRUCTIVE - files deleted cannot be recovered
#>

param (
    [Parameter(Mandatory=$true)]
    [string]$FilePath,

    [ValidateSet("Simple", "DoD", "Gutmann")]
    [string]$Method = "DoD"
)

function Test-Admin {
    $currentUser = New-Object Security.Principal.WindowsPrincipal([Security.Principal.WindowsIdentity]::GetCurrent())
    return $currentUser.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)
}

if (-not (Test-Admin)) {
    Write-Warning "This script should be run as Administrator for best results"
}

if (-not (Test-Path $FilePath)) {
    Write-Error "File not found: $FilePath"
    exit 1
}

function Secure-Delete {
    param (
        [string]$path,
        [string]$method
    )

    try {
        $fileStream = [System.IO.File]::Open($path, [System.IO.FileMode]::Open, [System.IO.FileAccess]::Write, [System.IO.FileShare]::None)
        $fileLength = $fileStream.Length

        switch ($method) {
            "Simple" {
                # Single pass with zeros
                $fileStream.SetLength(0)
                $fileStream.Write((New-Object byte[] $fileLength), 0, $fileLength)
            }
            "DoD" {
                # DoD 5220.22-M (3 passes)
                for ($i = 0; $i -lt 3; $i++) {
                    $fileStream.Position = 0
                    $pattern = if ($i -eq 0) { 0x00 } elseif ($i -eq 1) { 0xFF } else { (Get-Random -Maximum 256) }
                    $fileStream.Write((New-Object byte[] $fileLength -ArgumentList $pattern), 0, $fileLength)
                    $fileStream.Flush()
                }
            }
            "Gutmann" {
                # Gutmann method (35 passes)
                $patterns = @(
                    0x55, 0xAA, 0x92, 0x49, 0x24, 0x00, 0x11, 0x22, 0x33, 0x44, 0x55, 0x66, 0x77,
                    0x88, 0x99, 0xAA, 0xBB, 0xCC, 0xDD, 0xEE, 0xFF, 0x92, 0x49, 0x24, 0x00, 0x11,
                    0x22, 0x33, 0x44, 0x55, 0x66, 0x77, 0x88, 0x99, 0xAA
                )

                for ($i = 0; $i -lt 35; $i++) {
                    $fileStream.Position = 0
                    $pattern = if ($i -lt $patterns.Count) { $patterns[$i] } else { (Get-Random -Maximum 256) }
                    $fileStream.Write((New-Object byte[] $fileLength -ArgumentList $pattern), 0, $fileLength)
                    $fileStream.Flush()
                }
            }
        }

        $fileStream.Close()
        [System.IO.File]::Delete($path)
        Write-Host "File securely deleted: $path" -ForegroundColor Green
    }
    catch {
        Write-Error "Error deleting file: $_"
    }
}

Write-Host "Securely deleting file: $FilePath using $Method method..."
Secure-Delete -path $FilePath -method $Method
```

